// ------------------------------------------------------------------
// Query builder – builds up filters, then executes when needed
// ------------------------------------------------------------------
function createQuery(table) {
  const filters = [];
  let action = null;          // 'select', 'insert', 'update', 'delete', 'upsert'
  let dataPayload = null;
  let limitNum = null;
  let singleMode = false;
  let countMode = false, headOnly = false;
  let orderBy = null, orderAsc = true;

  const apply = () => {
    let rows = load(table);
    filters.forEach(f => {
      try {
        if (f.type === 'eq')      rows = rows.filter(r => r[f.col] === f.val);
        else if (f.type === 'gte') rows = rows.filter(r => new Date(r[f.col]) >= new Date(f.val));
        else if (f.type === 'lte') rows = rows.filter(r => new Date(r[f.col]) <= new Date(f.val));
        else if (f.type === 'not') rows = rows.filter(r => r[f.col] !== f.val);
        else if (f.type === 'is')  rows = rows.filter(r => r[f.col] === null);
      } catch {}
    });
    if (orderBy) {
      rows.sort((a, b) => (a[orderBy] > b[orderBy] ? 1 : -1) * (orderAsc ? 1 : -1));
    }
    return rows;
  };

  // ----- Execute the built‑up query -----
  const execute = () => {
    if (action === 'select') {
      const list = apply();
      let resultList = list;
      if (limitNum !== null) resultList = list.slice(0, limitNum);
      if (singleMode) {
        return makeThenable({ data: list[0] || null, error: null });
      }
      if (countMode) {
        return makeThenable({ count: headOnly ? list.length : apply().length, data: headOnly ? [] : resultList, error: null });
      }
      return makeThenable({ data: resultList, error: null });
    }

    if (action === 'insert') {
      const arr = Array.isArray(dataPayload) ? dataPayload : [dataPayload];
      const newRows = arr.map(d => ({ id: genID(), ...d }));
      const cur = load(table);
      save(table, [...cur, ...newRows]);
      // Return an object that also supports `.select().single()` as real Supabase does
      const result = makeThenable({ data: newRows, error: null });
      result.select = () => makeThenable({ data: newRows, error: null });
      result.single = () => makeThenable({ data: newRows[0] || null, error: null });
      return result;
    }

    if (action === 'update') {
      try {
        const cur = load(table);
        const updated = cur.map(r => {
          const match = filters.every(f => r[f.col] === f.val);
          return match ? { ...r, ...dataPayload } : r;
        });
        save(table, updated);
        return makeThenable({ error: null });
      } catch (e) { return makeThenable({ error: { message: e.message } }); }
    }

    if (action === 'delete') {
      try {
        const cur = load(table);
        const remaining = cur.filter(r => !filters.every(f => r[f.col] === f.val));
        save(table, remaining);
        return makeThenable({ error: null });
      } catch (e) { return makeThenable({ error: { message: e.message } }); }
    }

    if (action === 'upsert') {
      const cur = load(table);
      const arr = Array.isArray(dataPayload) ? dataPayload : [dataPayload];
      arr.forEach(d => {
        const idx = cur.findIndex(r => r.id === d.id);
        if (idx >= 0) cur[idx] = d;
        else cur.push({ id: genID(), ...d });
      });
      save(table, cur);
      return makeThenable({ error: null });
    }

    return makeThenable({ error: { message: 'No query action defined' } });
  };

  // ----- Proxy – intercepts method calls to build context -----
  const proxy = new Proxy({}, {
    get(target, prop) {
      // Terminal methods – execute and return thenable
      if (prop === 'then') return (resolve, reject) => resolve(execute());
      if (prop === 'catch') return (fn) => proxy; // ignore

      // Methods that set action
      if (prop === 'select') return (...args) => {
        action = 'select';
        if (args[1] && args[1].count === 'exact') {
          countMode = true;
          if (args[1].head) headOnly = true;
        }
        return proxy;
      };
      if (prop === 'insert') return (data) => {
        action = 'insert';
        dataPayload = data;
        return execute(); // insert directly returns result
      };
      if (prop === 'update') return (data) => {
        action = 'update';
        dataPayload = data;
        return proxy; // wait for .eq() / .in()
      };
      if (prop === 'delete') return () => {
        action = 'delete';
        return proxy; // wait for .eq()
      };
      if (prop === 'upsert') return (data) => {
        action = 'upsert';
        dataPayload = data;
        return execute();
      };
      if (prop === 'eq') return (col, val) => { filters.push({ type: 'eq', col, val }); return proxy; };
      if (prop === 'gte') return (col, val) => { filters.push({ type: 'gte', col, val }); return proxy; };
      if (prop === 'lte') return (col, val) => { filters.push({ type: 'lte', col, val }); return proxy; };
      if (prop === 'not') return (col, val) => { filters.push({ type: 'not', col, val }); return proxy; };
      if (prop === 'is') return (col, val) => { filters.push({ type: 'is', col, val }); return proxy; };
      if (prop === 'order') return (col, opt) => {
        orderBy = col;
        orderAsc = opt?.ascending !== false;
        return execute(); // order usually ends the chain
      };
      if (prop === 'limit') return (n) => {
        limitNum = n;
        return execute();
      };
      if (prop === 'single' || prop === 'maybeSingle') {
        singleMode = true;
        return execute();
      }
      if (prop === 'in') return (col, vals) => {
        // For .in(), we add a filter that checks if the value is in the array
        filters.push({ type: 'in', col, vals });
        return proxy;
      };

      // For any other property, just return a function that returns the proxy
      return () => proxy;
    }
  });

  return proxy;
}

